// test/SimplePool.t.sol
import {Test} from "forge-std/Test.sol";
import {SimplePool} from "../src/SimplePool.sol";
import {TeachingToken} from "../src/TeachingToken.sol";

contract SimplePoolTest is Test {
    SimplePool pool;
    TeachingToken tokenA;
    TeachingToken tokenB;

    function setUp() public {
        tokenA = new TeachingToken("TokenA", "TKA");
        tokenB = new TeachingToken("TokenB", "TKB");
        pool = new SimplePool(address(tokenA), address(tokenB));
    }

    // --- Step 1: happy path + the first-depositor branch ---
    function test_FirstDeposit_UsesSqrtFormula() public {
        tokenA.mint(address(this), 100e18);
        tokenB.mint(address(this), 400e18);
        tokenA.approve(address(pool), 100e18);
        tokenB.approve(address(pool), 400e18);

        uint256 minted = pool.addLiquidity(100e18, 400e18);
        assertEq(minted, 200e18); // sqrt(100e18 * 400e18)
    }

    // --- Step 2: Lesson 6's fuzz test, now a suite member ---
    function testFuzz_SwapNeverDecreasesConstantProduct(uint256 amountIn) public {
        _seedPool();
        amountIn = bound(amountIn, 1, 1_000e18);
        uint256 kBefore = pool.reserveA() * pool.reserveB();
        tokenA.mint(address(this), amountIn);
        tokenA.approve(address(pool), amountIn);
        pool.swapAforB(amountIn);
        assertGe(pool.reserveA() * pool.reserveB(), kBefore);
    }

    // --- Step 2b: the removeLiquidity side ---
    function testFuzz_RemoveLiquidityNeverExceedsShareOfPool(uint256 sharesToRemove) public {
        _seedPool();
        uint256 myShares = pool.shares(address(this));
        sharesToRemove = bound(sharesToRemove, 1, myShares);
        uint256 poolBalABefore = tokenA.balanceOf(address(pool));

        (uint256 amtA, ) = pool.removeLiquidity(sharesToRemove);
        assertLe(amtA, poolBalABefore); // never redeems more than the pool actually holds
    }

    function _seedPool() internal {
        tokenA.mint(address(this), 1_000e18);
        tokenB.mint(address(this), 4_000e18);
        tokenA.approve(address(pool), 1_000e18);
        tokenB.approve(address(pool), 4_000e18);
        pool.addLiquidity(1_000e18, 4_000e18);
    }
}
