// test/handlers/SimplePoolHandler.sol — Step 3
contract SimplePoolHandler is Test {
    SimplePool pool;
    TeachingToken tokenA;
    TeachingToken tokenB;
    address[] actors;

    constructor(SimplePool _pool, TeachingToken _a, TeachingToken _b) {
        pool = _pool; tokenA = _a; tokenB = _b;
        for (uint256 i = 0; i < 4; i++) actors.push(address(uint160(0x2000 + i)));
    }

    function addLiquidity(uint256 actorSeed, uint256 amtA, uint256 amtB) public {
        address actor = actors[actorSeed % actors.length];
        amtA = bound(amtA, 1e18, 500e18);
        amtB = bound(amtB, 1e18, 500e18);
        tokenA.mint(actor, amtA);
        tokenB.mint(actor, amtB);
        vm.startPrank(actor);
        tokenA.approve(address(pool), amtA);
        tokenB.approve(address(pool), amtB);
        pool.addLiquidity(amtA, amtB);
        vm.stopPrank();
    }

    function swap(uint256 actorSeed, uint256 amountIn) public {
        address actor = actors[actorSeed % actors.length];
        if (pool.reserveA() == 0) return;
        amountIn = bound(amountIn, 1, 100e18);
        tokenA.mint(actor, amountIn);
        vm.startPrank(actor);
        tokenA.approve(address(pool), amountIn);
        pool.swapAforB(amountIn);
        vm.stopPrank();
    }
}
