**The contract**: `SimpleNFTMarketplace` from Lesson 9, specifically `buyItem` and its private `_pay` helper, which sends ETH with a low-level `call` and reverts the whole transaction if that call fails:

```solidity
function buyItem(address nft, uint256 tokenId) external payable nonReentrant {
    Listing memory listing = listings[nft][tokenId];
    require(listing.price > 0, "not listed");
    require(msg.value == listing.price, "wrong price");
    delete listings[nft][tokenId];
    (address royaltyReceiver, uint256 royaltyAmount) = _royaltyFor(nft, tokenId, listing.price);
    IERC721(nft).safeTransferFrom(listing.seller, msg.sender, tokenId);
    if (royaltyAmount > 0 && royaltyReceiver != address(0)) {
        _pay(royaltyReceiver, royaltyAmount); // <- push payment, can fail
    }
    _pay(listing.seller, listing.price - royaltyAmount); // <- push payment, can fail
    emit Sale(nft, tokenId, msg.sender, listing.price);
}

function _pay(address to, uint256 amount) private {
    (bool ok, ) = to.call{value: amount}("");
    require(ok, "payment transfer failed");
}
