// Fixed: pull payments instead of push payments
contract SimpleNFTMarketplaceFixed is ReentrancyGuard {
    struct Listing {
        address seller;
        uint256 price;
    }

    mapping(address => mapping(uint256 => Listing)) public listings;
    mapping(address => uint256) public pendingWithdrawals; // <- new

    event Listed(address indexed nft, uint256 indexed tokenId, address indexed seller, uint256 price);
    event Sale(address indexed nft, uint256 indexed tokenId, address indexed buyer, uint256 price);

    function buyItem(address nft, uint256 tokenId) external payable nonReentrant {
        Listing memory listing = listings[nft][tokenId];
        require(listing.price > 0, "not listed");
        require(msg.value == listing.price, "wrong price");

        delete listings[nft][tokenId];

        (address royaltyReceiver, uint256 royaltyAmount) = _royaltyFor(nft, tokenId, listing.price);

        IERC721(nft).safeTransferFrom(listing.seller, msg.sender, tokenId);

        // Credit balances instead of pushing ETH -- no external call here
        // that can revert this transaction.
        if (royaltyAmount > 0 && royaltyReceiver != address(0)) {
            pendingWithdrawals[royaltyReceiver] += royaltyAmount;
        }
        pendingWithdrawals[listing.seller] += (listing.price - royaltyAmount);

        emit Sale(nft, tokenId, msg.sender, listing.price);
    }

    function withdrawPayments() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "nothing to withdraw");
        pendingWithdrawals[msg.sender] = 0; // effects before interaction
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "withdrawal failed");
    }

    // _royaltyFor unchanged from Lesson 9
}
