// test/SimpleNFTMarketplace.griefing.t.sol — proves the original bug, then the fix
contract RevertingReceiver {
    receive() external payable {
        revert("I refuse ETH");
    }
}

contract GriefingTest is Test {
    function test_OriginalContract_SaleBlockedByRevertingRoyaltyReceiver() public {
        RevertingReceiver badReceiver = new RevertingReceiver();
        // ...mint NFT, set badReceiver as the ERC-2981 royalty receiver,
        // list it, then attempt to buy:
        vm.expectRevert("payment transfer failed");
        marketplace.buyItem{value: 1 ether}(nft, tokenId);
        // The listing is now permanently unbuyable -- the seller can
        // cancel and re-list, but cannot ever sell to this exact flow
        // again while that collection's royalty receiver stays broken.
    }

    function test_FixedContract_SaleSucceedsRegardlessOfReceiver() public {
        RevertingReceiver badReceiver = new RevertingReceiver();
        // ...same setup, against SimpleNFTMarketplaceFixed:
        marketplaceFixed.buyItem{value: 1 ether}(nft, tokenId); // does not revert
        assertGt(marketplaceFixed.pendingWithdrawals(address(badReceiver)), 0);
        // badReceiver's own broken receive() is now its own problem --
        // the sale itself completed for the buyer and the seller.
    }
}
