// test/DAOLifecycle.t.sol
import {Test} from "forge-std/Test.sol";
import {GovernanceToken} from "../src/GovernanceToken.sol";
import {TreasuryTimelock} from "../src/TreasuryTimelock.sol";
import {ProjectGovernor} from "../src/ProjectGovernor.sol";
import {IGovernor} from "@openzeppelin/contracts/governance/IGovernor.sol";

contract DAOLifecycleTest is Test {
    GovernanceToken token;
    TreasuryTimelock timelock;
    ProjectGovernor governor;
    address deployer = address(this);
    address holderA = address(0xA1);
    address holderB = address(0xA2);
    address minorityHolder = address(0xA3);

    function setUp() public {
        // Step 1: deploy and hand off
        token = new GovernanceToken(deployer, 1_000_000e18);
        token.transfer(holderA, 400_000e18);
        token.transfer(holderB, 400_000e18);
        token.transfer(minorityHolder, 1_000e18); // well under 4% of supply

        vm.prank(holderA); token.delegate(holderA);
        vm.prank(holderB); token.delegate(holderB);
        vm.prank(minorityHolder); token.delegate(minorityHolder);
        token.delegate(deployer);

        address[] memory proposers = new address[](0);
        address[] memory executors = new address[](0);
        timelock = new TreasuryTimelock(2 days, proposers, executors, deployer);
        governor = new ProjectGovernor(token, timelock);

        timelock.grantRole(timelock.PROPOSER_ROLE(), address(governor));
        timelock.grantRole(timelock.EXECUTOR_ROLE(), address(0));
        timelock.renounceRole(timelock.DEFAULT_ADMIN_ROLE(), deployer);

        assertFalse(timelock.hasRole(timelock.DEFAULT_ADMIN_ROLE(), deployer));
    }

    function test_ProposalSucceedsAndExecutes() public {
        (uint256 proposalId, address[] memory t, uint256[] memory v, bytes[] memory c, string memory d) = _buildProposal();
        governor.propose(t, v, c, d);

        vm.roll(block.number + governor.votingDelay() + 1);

        vm.prank(holderA); governor.castVote(proposalId, 1); // for
        vm.prank(holderB); governor.castVote(proposalId, 1); // for

        vm.roll(block.number + governor.votingPeriod() + 1);
        assertEq(uint8(governor.state(proposalId)), uint8(IGovernor.ProposalState.Succeeded));

        governor.queue(t, v, c, keccak256(bytes(d)));
        vm.warp(block.timestamp + timelock.getMinDelay() + 1);
        governor.execute(t, v, c, keccak256(bytes(d)));

        assertEq(uint8(governor.state(proposalId)), uint8(IGovernor.ProposalState.Executed));
    }

    function test_ProposalFailsQuorum_CannotBeQueued() public {
        (uint256 proposalId, address[] memory t, uint256[] memory v, bytes[] memory c, string memory d) = _buildProposal();
        governor.propose(t, v, c, d);

        vm.roll(block.number + governor.votingDelay() + 1);
        vm.prank(minorityHolder); governor.castVote(proposalId, 1); // ~0.1% of supply -- well under 4%
        vm.roll(block.number + governor.votingPeriod() + 1);

        assertEq(uint8(governor.state(proposalId)), uint8(IGovernor.ProposalState.Defeated));

        vm.expectRevert();
        governor.queue(t, v, c, keccak256(bytes(d)));
    }

    function _buildProposal() internal view returns (uint256, address[] memory, uint256[] memory, bytes[] memory, string memory) {
        address[] memory targets = new address[](1);
        uint256[] memory values = new uint256[](1);
        bytes[] memory calldatas = new bytes[](1);
        targets[0] = address(treasury);
        calldatas[0] = abi.encodeCall(Treasury.releaseFunds, (holderA, 10e18));
        string memory description = "Release 10 tokens to holderA for completed work";
        uint256 proposalId = governor.hashProposal(targets, values, calldatas, keccak256(bytes(description)));
        return (proposalId, targets, values, calldatas, description);
    }
}
